import{_ as p,r as n,o as l,c as o,e as s,a as c,s as r}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"Столбец Partial - October CMS - 3.x","titleTemplate":false,"description":"Столбец списка","frontmatter":{"subtitle":"Столбец списка","shortname":"Partial"},"headers":[{"level":2,"title":"Использование шаблонов представлений","slug":"использование-шаблонов-представлении","link":"#использование-шаблонов-представлении","children":[{"level":4,"title":"См. также","slug":"см-также","link":"#см-также","children":[]}]}],"relativePath":"3.x/ru/element/lists/column-partial.md","filePath":"3.x/ru/element/lists/column-partial.md"}'),i={name:"3.x/ru/element/lists/column-partial.md"};function u(d,a,k,m,h,g){const t=n("pre-heading"),e=n("post-heading");return l(),o("div",null,[s(t),a[0]||(a[0]=c("h1",null,"Столбец Partial",-1)),s(e),a[1]||(a[1]=r(`<p>Столбец <code>partial</code> рендерит содержимое столбца с использованием частичного представления или файла представления. Значение <code>path</code> может ссылаться на файл частичного представления, иначе имя столбца используется как имя представления. Область видимости по умолчанию для пути представления — путь представлений контроллера.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">content</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Content
    <span class="token key atrule">type</span><span class="token punctuation">:</span> partial
    <span class="token key atrule">path</span><span class="token punctuation">:</span> content_column
</code></pre></div><p>Поддерживаются следующие свойства.</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th></tr></thead><tbody><tr><td><strong>path</strong></td><td>путь к <a href="./../../extend/system/views.html">файлу частичного представления</a> или <a href="./../../extend/services/response-view.html">коду шаблона представления</a>, по умолчанию — имя столбца с префиксом <strong>column_</strong>.</td></tr></tbody></table></div><p>Когда <code>path</code> задан как неквалифицированное имя файла (имя файла без пути к директории и расширения), исходный путь определяется в директориях модели или контроллера. Следующий пример будет искать файл частичного представления по пути <strong>../models/mymodel/_column_for_content.php</strong> или <strong>../controllers/mycontroller/_column_for_content.php</strong>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">content</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> partial
    <span class="token key atrule">path</span><span class="token punctuation">:</span> column_for_content
</code></pre></div><p>Вы можете указать полный <code>path</code> для доступа к частичным представлениям вне директорий модели или контроллера. Это может быть полезно для совместного использования частичных представлений между определениями.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">content</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Content
    <span class="token key atrule">type</span><span class="token punctuation">:</span> partial
    <span class="token key atrule">path</span><span class="token punctuation">:</span> $/acme/blog/partials/_content_column.php
</code></pre></div><p>Внутри частичного представления доступны следующие переменные.</p><ul><li><code>$value</code> — значение ячейки по умолчанию.</li><li><code>$record</code> — модель, используемая для ячейки.</li><li><code>$column</code> — сконфигурированный объект класса <code>Backend\\Classes\\ListColumn</code>.</li></ul><p>Вот пример содержимого файла <strong>_content_column.php</strong>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$record</span><span class="token operator">-&gt;</span><span class="token property">is_active</span><span class="token punctuation">)</span><span class="token punctuation">:</span> <span class="token delimiter important">?&gt;</span></span>
    <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token function">e</span><span class="token punctuation">(</span><span class="token variable">$value</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
<span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">endif</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><h2 id="использование-шаблонов-представлении"><a href="#использование-шаблонов-представлении" class="header-anchor">#</a> Использование шаблонов представлений</h2><p>Вы можете передать код шаблона представления в <code>path</code> для доступа к шаблонам сервиса представлений внутри плагина. Следующий код будет найден по пути <strong>plugins/acme/blog/views/listcolumns/content.php</strong>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">content</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Content
    <span class="token key atrule">type</span><span class="token punctuation">:</span> partial
    <span class="token key atrule">path</span><span class="token punctuation">:</span> acme.blog<span class="token punctuation">:</span><span class="token punctuation">:</span>listcolumns.content
</code></pre></div><div class="custom-block tip"><p>Путь должен содержать символы <code>::</code> для активации сервиса представлений.</p></div><h4 id="см-также"><a href="#см-также" class="header-anchor">#</a> См. также</h4><div class="custom-block also"><ul><li><a href="./../../extend/system/views.html">Рендеринг представлений контроллера</a></li><li><a href="./../../extend/services/response-view.html">Сервис ответов и представлений</a></li></ul></div>`,18))])}const v=p(i,[["render",u]]);export{y as __pageData,v as default};
